/* ============================================================
   HERO SCENE: dot portrait + linked node graph
   ------------------------------------------------------------
   The portrait is a halftone print plate: an even grid of circles
   whose size and colour carry the photograph's tone. The cursor
   repels the dots and they settle back on a spring.

   Behind it floats a graph in the manner of an Obsidian vault. The
   content is a three-level tree (see hero-graph-data.js): eight
   hubs spoke inward to a single point behind the portrait, their
   branches fan outward from each hub, and the leaves fan outward
   again from each branch. Hubs and branches are labelled at rest;
   a leaf shows its label when its branch is hovered or tapped.
   Click any node to read what it holds.

   Spokes converge on that centre rather than terminating on the
   silhouette. Tying them to his outline tethered the graph to his
   edges; a centre lets the clusters float free behind him.

   Append ?portrait=off to the URL to preview without the graph.
   ============================================================ */
(function (global) {
  'use strict';

  var MAP_SRC = 'data:image/png;base64,';
  var MAP_W = 210, MAP_H = 218;
  var TAU = Math.PI * 2;
  var LEVELS = 16;

  /* Portrait ramp. It has to carry as much tone as dot size does, because a narrow
     ramp flattens the face into one mass however the sizes are tuned. Bright
     areas of the photograph stay most present in both themes, so the portrait
     never reads as a negative. */
  var RAMPS = {
    dark:  [[92, 30, 5], [230, 88, 10], [255, 192, 132]],
    /* Gold on cream, in the headline's own family. Pale where he is dark,
       deepest where the light hits, so it still reads as a positive. */
    light: [[202, 184, 138], [156, 116, 24], [66, 44, 2]]
  };

  /* Nodes sit at REST_ALPHA in a single neutral tone and only take their
     branch colour under the cursor. At rest the graph is a quiet structure
     around him; colour is the reward for reaching for one. Kept in RGB so the
     two states can be blended per frame. */
  var REST_ALPHA = 0.4;

  var NODE_COLORS = {
    dark: {
      rest: [168, 156, 142], sat: 0.62, light: 0.62,
      edge: [180, 150, 120], edgeA: 0.11,
      edgeHot: [255, 150, 70], edgeHotA: 0.5
    },
    /* Light mode runs gold, tuned to the same family as the headline's
       --primary (#8A6410), rather than the neutral charcoal it used to be. */
    light: {
      rest: [138, 100, 16], sat: 0.58, light: 0.38,
      edge: [150, 112, 26], edgeA: 0.15,
      edgeHot: [138, 88, 8], edgeHotA: 0.55
    }
  };

  /* One row per tree level: dot radius (desktop / compact), the minimum
     centre-to-centre distance to any other node, the label face and how
     bright a resting label sits. The leaf row never rests with its label on,
     so its restA only matters once revealed. */
  var MONO = '"JetBrains Mono", ui-monospace, monospace';
  var LEVEL = {
    1: { font: '500 11px ' + MONO,  size: 11,  r: 6,   rc: 4.6, gap: 52, gapc: 30, restA: 0.74 },
    2: { font: '400 9.5px ' + MONO, size: 9.5, r: 3.6, rc: 2.8, gap: 26, gapc: 16, restA: 0.6 },
    3: { font: '400 9px ' + MONO,   size: 9,   r: 2.2, rc: 1.8, gap: 14, gapc: 10, restA: 0.55 }
  };
  var LABEL_GAP = 6;        // dot edge to the first glyph
  var LABEL_PAD_X = 4;      // clearance kept between label boxes
  var LABEL_PAD_Y = 3;

  /* The content comes from hero-graph-data.js. Without it the portrait still
     draws; the graph just has nothing to say. */
  function graphData() {
    var g = global.HERO_GRAPH;
    if (!g || !Array.isArray(g.hubs) || !g.hubs.length) {
      if (global.console) {
        console.warn('hero-scene: window.HERO_GRAPH is missing or empty. ' +
          'Load hero-graph-data.js before hero-scene.js. Drawing the portrait without its graph.');
      }
      return { hubs: [], crossLinks: [] };
    }
    return { hubs: g.hubs, crossLinks: Array.isArray(g.crossLinks) ? g.crossLinks : [] };
  }

  /* Branch colours are generated from one hue each so both themes stay
     legible without maintaining two hand-picked palettes. */
  function hslToRgb(h, s, l) {
    h = (h % 360) / 360;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h * 6) % 2) - 1));
    var m = l - c / 2, r = 0, g = 0, b = 0, k = Math.floor(h * 6);
    if (k === 0) { r = c; g = x; }
    else if (k === 1) { r = x; g = c; }
    else if (k === 2) { g = c; b = x; }
    else if (k === 3) { g = x; b = c; }
    else if (k === 4) { r = x; b = c; }
    else { r = c; b = x; }
    return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)];
  }

  function lerp(a, b, t) { return a + (b - a) * t; }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

  function mixRgb(a, b, t) {
    return 'rgb(' + Math.round(lerp(a[0], b[0], t)) + ',' +
                    Math.round(lerp(a[1], b[1], t)) + ',' +
                    Math.round(lerp(a[2], b[2], t)) + ')';
  }

  function rampColor(ramp, t) {
    var lo = ramp[0], mid = ramp[1], hi = ramp[2], a, b, k;
    if (t < 0.5) { a = lo; b = mid; k = t * 2; }
    else { a = mid; b = hi; k = (t - 0.5) * 2; }
    return mixRgb(a, b, k);
  }

  /* Seeded RNG so the graph's layout is identical on every load. A layout that
     reshuffles on refresh reads as noise rather than as a structure. */
  function rng(seed) {
    var s = seed >>> 0;
    return function () {
      s = (s * 1664525 + 1013904223) >>> 0;
      return s / 4294967296;
    };
  }

  /* ---- one decode of the luminance map for the whole page ---- */
  var mapPromise = null;
  function loadMap() {
    if (mapPromise) return mapPromise;
    mapPromise = new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () {
        var c = document.createElement('canvas');
        c.width = MAP_W; c.height = MAP_H;
        var g = c.getContext('2d', { willReadFrequently: true });
        if (!g) { reject(new Error('no 2d context')); return; }
        g.drawImage(img, 0, 0, MAP_W, MAP_H);
        try { resolve(g.getImageData(0, 0, MAP_W, MAP_H).data); }
        catch (e) { reject(e); }
      };
      img.onerror = function () { reject(new Error('map failed to load')); };
      img.src = MAP_SRC;
    });
    return mapPromise;
  }

  /* Labels are measured at build time with the same face they are drawn in,
     so the layout should not run before the mono font is in. A slow font
     must not hold the hero hostage though, so this gives up after a moment
     and the scene rebuilds once the font does land. */
  function fontsSettled() {
    if (!document.fonts || !document.fonts.ready) return Promise.resolve();
    return Promise.race([
      document.fonts.ready,
      new Promise(function (r) { setTimeout(r, 1500); })
    ]).catch(function () { /* nothing to wait for */ });
  }

  /* ============================================================
     Scene
     ============================================================ */
  function HeroScene(canvas, opts) {
    opts = opts || {};
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.card = opts.card || null;
    this.withGraph = opts.withGraph !== false;
    this.crop = opts.crop || null;    // u0,v0,u1,v1 sub-rect of the map
    this.fill = !!opts.fill;          // portrait fills the canvas (nav mark)

    this.spacing = 2.5;
    this.dotScale = 0.45;
    this.floor = 0.30;
    this.radius = 118;        // pointer influence radius, CSS px
    this.strength = 24;       // max dot displacement, CSS px

    this.dots = null;
    this.nodes = [];
    this.edges = [];
    this.links = [];
    this.pointer = { x: -9999, y: -9999, inside: false };
    this.hover = null;
    this.selected = null;
    this.running = false;
    this.visible = true;
    this.mobile = false;
    this.t = 0;

    this.reduced = !!(global.matchMedia &&
      global.matchMedia('(prefers-reduced-motion: reduce)').matches);

    /* Cache of the portrait at rest. Nodes drift constantly, so without this
       every frame would re-path several thousand arcs to redraw an image that
       has not changed. */
    this.cache = null;
    this.cacheValid = false;

    this._frame = this._frame.bind(this);
    this._onResize = this._onResize.bind(this);
  }

  HeroScene.prototype.init = function () {
    var self = this;
    var waits = [loadMap()];
    if (this.withGraph) waits.push(fontsSettled());
    return Promise.all(waits).then(function (got) {
      self.map = got[0];
      self.build();
      self.bind();
      self.start();
      /* If the font was still loading when we gave up waiting, the labels
         were measured in the fallback face. Lay out again once it lands. */
      if (self.withGraph && document.fonts && document.fonts.status !== 'loaded') {
        document.fonts.ready.then(function () { self.rebuild(); });
      }
      return self;
    });
  };

  HeroScene.prototype.sample = function (u, v) {
    var c = this.crop;
    var mu = (c ? c[0] + u * (c[2] - c[0]) : u) * (MAP_W - 1);
    var mv = (c ? c[1] + v * (c[3] - c[1]) : v) * (MAP_H - 1);
    var x0 = clamp(Math.floor(mu), 0, MAP_W - 1), y0 = clamp(Math.floor(mv), 0, MAP_H - 1);
    var x1 = Math.min(x0 + 1, MAP_W - 1), y1 = Math.min(y0 + 1, MAP_H - 1);
    var fx = mu - x0, fy = mv - y0, d = this.map;
    function at(x, y, o) { return d[(y * MAP_W + x) * 4 + o] / 255; }
    return [
      lerp(lerp(at(x0, y0, 0), at(x1, y0, 0), fx),
           lerp(at(x0, y1, 0), at(x1, y1, 0), fx), fy),
      lerp(lerp(at(x0, y0, 3), at(x1, y0, 3), fx),
           lerp(at(x0, y1, 3), at(x1, y1, 3), fx), fy)
    ];
  };

  HeroScene.prototype.build = function () {
    /* Layout size, not the painted size. The nav mark is revealed with a CSS
       scale, and a measured rect would report it mid-transform. */
    var w = this.canvas.offsetWidth, h = this.canvas.offsetHeight;
    if (!w || !h) return;

    var dpr = Math.min(global.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.w = w; this.h = h; this.dpr = dpr;
    this.compact = w < 900;
    /* Below this the graph shows hub labels only and opens a branch on tap;
       there is no room for thirty resting labels on a phone. */
    this.mobile = (global.innerWidth || w) < 640;
    /* Grid pitch drives how much face survives. The crop carries full shoulders
       now, so the head is a smaller share of the frame than it was on the tight
       crop, so the pitch has to come down to put the detail back. The nav mark
       sets its own. */
    if (!this.fill) this.spacing = this.compact ? 2.0 : 2.5;

    this.buildPortrait();
    if (this.withGraph) this.buildGraph();
    this.applyTheme();
  };

  HeroScene.prototype.rebuild = function () {
    this.select(null);
    this.setHover(null);
    this.nodes = []; this.edges = []; this.links = [];
    this.build();
    this.start();
  };

  HeroScene.prototype.buildPortrait = function () {
    var w = this.w, h = this.h;
    var c = this.crop;
    var mapAspect = c ? ((c[2] - c[0]) * MAP_W) / ((c[3] - c[1]) * MAP_H)
                      : MAP_W / MAP_H;

    /* Fit the portrait into the right of the hero on wide screens, and centre
       it above the copy once the layout stacks. */
    var pH, pW, px0, py0;
    if (this.fill) {
      /* Nav mark: aspect-fit the whole canvas. */
      pH = h; pW = h * mapAspect;
      if (pW > w) { pW = w; pH = w / mapAspect; }
      px0 = (w - pW) / 2; py0 = (h - pH) / 2;
    } else if (this.compact) {
      /* Centred above the copy, held back from the full width so the graph
         still has margins to live in. */
      pH = h * 0.62;
      pW = pH * mapAspect;
      if (pW > w * 0.58) { pW = w * 0.58; pH = pW / mapAspect; }
      px0 = (w - pW) / 2;
      py0 = (h - pH) / 2;
    } else {
      /* Matched to the copy block: he stands the same height as the text
         beside him and shares its baseline, so the two halves of the hero
         read as one composition rather than a column and a decoration. */
      var copy = this.copyBox();
      pH = copy ? copy.height : h * 0.62;
      pW = pH * mapAspect;

      /* Whatever is left to the right of the copy, minus room for the graph. */
      var leftEdge = copy ? copy.right : w * 0.44;
      var avail = w - leftEdge;
      if (pW > avail * 0.86) { pW = avail * 0.86; pH = pW / mapAspect; }

      px0 = leftEdge + (avail - pW) / 2;
      py0 = copy ? copy.top + (copy.height - pH) / 2 : (h - pH) / 2;
    }

    this.portrait = { x: px0, y: py0, w: pW, h: pH,
                      cx: px0 + pW / 2, cy: py0 + pH / 2 };

    var sp = this.spacing;
    var cols = Math.max(1, Math.floor(pW / sp));
    var rows = Math.max(1, Math.floor(pH / sp));
    var padX = px0 + (pW - cols * sp) / 2 + sp / 2;
    var padY = py0 + (pH - rows * sp) / 2 + sp / 2;
    var maxR = sp * this.dotScale;
    var dots = [];
    var rand = rng(20260731);

    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        var s = this.sample((c + 0.5) / cols, (r + 0.5) / rows);
        var lum = s[0], alpha = s[1];
        if (alpha < 0.42) continue;

        /* Fray the silhouette edge so it dithers into the page rather than
           ending on a clean cut. */
        var edge = Math.min(1, (alpha - 0.42) / 0.28);

        /* The crop ends mid-torso, so without this the body would finish on a
           dead straight line across the hero. Dissolve the bottom instead. */
        var vy = (r + 0.5) / rows;
        if (vy > 0.62) {
          var f = 1 - (vy - 0.62) / 0.38;
          edge *= f * f * (3 - 2 * f);
        }

        if (edge < 1 && rand() > edge * 0.85 + 0.15) continue;

        /* Exponent > 1 keeps midtones visibly smaller than highlights, and
           dotScale < 0.5 leaves a gap even at full size, so the face never
           fills in solid. The floor keeps the near-black hair and quarter-zip
           present. Without it the portrait is a face floating in nothing. */
        var size = this.floor + (1 - this.floor) * Math.pow(lum, 1.25);
        var rr = maxR * size * (0.5 + edge * 0.5);
        if (rr < 0.26) continue;

        dots.push({
          x: padX + c * sp, y: padY + r * sp,
          dx: 0, dy: 0, vx: 0, vy: 0, r: rr,
          lvl: Math.min(LEVELS - 1, Math.floor(lum * LEVELS))
        });
      }
    }
    this.dots = dots;
  };

  /* Where the type actually is, not where its box is. `.hero__name` and
     `.hero__actions` are block/flex children of an 860px column, so their
     boxes report 860px while the words inside stop at 580. Ranging over the
     contents gives the real inked extent, which is what the portrait has to
     clear and what the graph has to work around. */
  var COPY_SEL = '.hero__status, .hero__name, .hero__subtitle, .hero__desc, .hero__actions';

  function inkedRect(el) {
    var r = document.createRange();
    r.selectNodeContents(el);
    var b = r.getBoundingClientRect();
    return b.width ? b : el.getBoundingClientRect();
  }

  /* The copy block's real extent: top of the status badge to the bottom of
     the buttons, and the widest line in between. */
  HeroScene.prototype.copyBox = function () {
    var base = this.canvas.getBoundingClientRect();
    var els = document.querySelectorAll(COPY_SEL);
    var top = Infinity, bottom = -Infinity, right = -Infinity;
    for (var i = 0; i < els.length; i++) {
      /* Widest of the two: the portrait has to clear both the visible words
         and the box that swallows pointer events. */
      var ink = inkedRect(els[i]), box = els[i].getBoundingClientRect();
      var r = ink.right >= box.right ? ink : box;
      if (!r.width) continue;
      top = Math.min(top, r.top - base.top);
      bottom = Math.max(bottom, r.bottom - base.top);
      right = Math.max(right, r.right - base.left);
    }
    if (top === Infinity) return null;
    return { top: top, bottom: bottom, height: bottom - top, right: right };
  };

  /* Rectangles the graph must not cover. These use the element box, not the
     inked rect: the box is what captures pointer events, and `.hero__desc`
     runs 33px wider than its longest line. A node resting in that gap looks
     free but is unclickable. The default pad also covers the node's drift
     amplitude, so one placed legally cannot wander under the copy. Labels
     pass a smaller pad: they are not click targets, they only need to stay
     visibly clear of the type. */
  HeroScene.prototype.keepOutRects = function (pad) {
    var base = this.canvas.getBoundingClientRect();
    var els = document.querySelectorAll(COPY_SEL);
    var out = [];
    if (pad == null) pad = 24;
    for (var i = 0; i < els.length; i++) {
      var r = els[i].getBoundingClientRect();
      if (!r.width) continue;
      out.push({ x0: r.left - base.left - pad, y0: r.top - base.top - pad,
                 x1: r.right - base.left + pad, y1: r.bottom - base.top + pad });
    }
    return out;
  };

  /* ============================================================
     Graph layout
     ============================================================ */
  HeroScene.prototype.buildGraph = function () {
    var data = graphData();
    this.nodes = []; this.edges = []; this.links = [];
    this.layoutInfo = { seed: null, overlaps: 0, collapsed: 0, ms: 0 };
    if (!data.hubs.length) return;

    /* The layout is label-aware from the first node, so a seed normally
       lands clean. If one does not, a few others are tried and the best is
       kept; whatever still collides folds its label away until hovered. */
    var t0 = global.performance ? performance.now() : Date.now();
    var seeds = [8675309, 1234567, 42424242, 20260801];
    var best = null;
    for (var s = 0; s < seeds.length; s++) {
      var out = this.layoutGraph(data, seeds[s]);
      if (!best || out.overlaps < best.overlaps) best = out;
      if (!out.overlaps) break;
    }
    var collapsed = best.overlaps ? this.collapseOverlaps(best.nodes) : 0;

    this.nodes = best.nodes;
    this.edges = best.edges;
    this.links = best.links;
    this.layoutInfo = {
      seed: best.seed, overlaps: best.overlaps, collapsed: collapsed,
      ms: Math.round(((global.performance ? performance.now() : Date.now()) - t0) * 10) / 10
    };
    this.renderA11yList(data);
  };

  HeroScene.prototype.layoutGraph = function (data, seed) {
    var self = this, p = this.portrait, rand = rng(seed);
    var ctx = this.ctx, w = this.w, h = this.h;
    var cx = p.cx, cy = p.cy;
    var compact = this.compact, mobile = this.mobile;
    var keepOut = compact ? [] : this.keepOutRects();
    var keepOutL = compact ? [] : this.keepOutRects(10);
    var theme = NODE_COLORS[document.documentElement.classList.contains('light')
      ? 'light' : 'dark'];
    var nodes = [], edges = [], links = [];
    var labels = [];      // boxes of every label that is on at rest
    var maxR = Math.hypot(w, h) * 0.75;
    var i, j, k;

    function inRect(x, y, r) { return x > r.x0 && x < r.x1 && y > r.y0 && y < r.y1; }
    function boxesHit(a, b) { return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0; }
    function onHim(x, y, thr) {
      if (x <= p.x || x >= p.x + p.w || y <= p.y || y >= p.y + p.h) return false;
      return self.sample((x - p.x) / p.w, (y - p.y) / p.h)[1] > thr;
    }
    function sideFor(x) { return x >= cx ? 1 : -1; }

    /* A hub wants room for a subtree, not just a legal dot. A ring of
       samples around the candidate has to be mostly clear of the copy, him
       and the canvas edge, which steers hubs out of thin strips and into the
       open bands above and below him. Only hubs set this, and only on
       their first pass. */
    var roomTest = null;
    var roomR = compact ? 40 : 64;
    function roomAt(x, y) {
      var ok = 0;
      for (var k = 0; k < 8; k++) {
        var a = (k / 8) * TAU, sx = x + Math.cos(a) * roomR, sy = y + Math.sin(a) * roomR;
        if (sx < 14 || sx > w - 14 || sy < 12 || sy > h - 12) continue;
        var blocked = false;
        for (var q = 0; q < keepOut.length && !blocked; q++) if (inRect(sx, sy, keepOut[q])) blocked = true;
        if (!blocked && onHim(sx, sy, 0.22)) blocked = true;
        if (!blocked) ok++;
      }
      return ok >= (compact ? 5 : 6);
    }

    /* The copy keep-out is never negotiable. A node under the paragraph looks
       placed but cannot be clicked, and an unreachable node is worse than a
       crowded one, so only the spacing between nodes is allowed to give. */
    function free(x, y, gap) {
      if (x < 14 || x > w - 14 || y < 12 || y > h - 12) return false;
      for (var q = 0; q < keepOut.length; q++) {
        if (inRect(x, y, keepOut[q])) return false;
      }
      /* Never on top of him. He is the index note, not a canvas. */
      if (onHim(x, y, 0.22)) return false;
      if (roomTest && !roomTest(x, y)) return false;
      for (var n = 0; n < nodes.length; n++) {
        if (Math.hypot(nodes[n].bx - x, nodes[n].by - y) < gap) return false;
      }
      /* Nor on anyone's resting label. */
      for (var l = 0; l < labels.length; l++) {
        var b = labels[l];
        if (x > b.x0 - 3 && x < b.x1 + 3 && y > b.y0 - 3 && y < b.y1 + 3) return false;
      }
      return true;
    }

    /* The box a label occupies for a node at (x, y), reading toward `side`
       (+1 right, -1 left), padded by the clearance kept between labels. */
    function labelBox(spec, tw, r, x, y, side) {
      var x0 = side > 0 ? x + r + LABEL_GAP : x - r - LABEL_GAP - tw;
      var hh = spec.size * 0.62;
      return { x0: x0 - LABEL_PAD_X, x1: x0 + tw + LABEL_PAD_X,
               y0: y - hh - LABEL_PAD_Y, y1: y + hh + LABEL_PAD_Y };
    }

    /* A label has to sit on the canvas, off the copy, off him, and clear of
       every resting label and every placed dot. `extra` carries the boxes of
       labels that will show at the same moment as this one (its siblings,
       and on a phone the branches of the same hub) so a reveal does not
       stack them on top of each other. */
    function labelFree(b, extra) {
      if (b.x0 < 2 || b.x1 > w - 2 || b.y0 < 2 || b.y1 > h - 2) return false;
      var q, n, sx;
      for (q = 0; q < keepOutL.length; q++) if (boxesHit(b, keepOutL[q])) return false;
      for (q = 0; q < labels.length; q++) if (boxesHit(b, labels[q])) return false;
      if (extra) for (q = 0; q < extra.length; q++) if (boxesHit(b, extra[q])) return false;
      for (n = 0; n < nodes.length; n++) {
        var nn = nodes[n];
        if (nn.bx > b.x0 - nn.r && nn.bx < b.x1 + nn.r &&
            nn.by > b.y0 - nn.r && nn.by < b.y1 + nn.r) return false;
      }
      if (b.x1 < p.x || b.x0 > p.x + p.w || b.y1 < p.y || b.y0 > p.y + p.h) return true;
      var ym = (b.y0 + b.y1) / 2;
      for (sx = b.x0; sx < b.x1 + 8; sx += 8) {
        var x = Math.min(sx, b.x1);
        if (onHim(x, b.y0 + 3, 0.18) || onHim(x, ym, 0.18) || onHim(x, b.y1 - 3, 0.18)) return false;
      }
      return true;
    }

    /* One candidate position. `strict` wants the label clear as well as the
       dot; otherwise the dot alone has to be legal and the label is placed
       on whichever side is clearer. */
    function tryAt(x, y, gap, spec, tw, r, strict, extra) {
      if (!free(x, y, gap)) return null;
      var pref = sideFor(x), sides = [pref, -pref];
      for (var s = 0; s < 2; s++) {
        var b = labelBox(spec, tw, r, x, y, sides[s]);
        if (labelFree(b, extra)) return { x: x, y: y, side: sides[s], box: b, labelled: true };
      }
      if (strict) return null;
      /* Unlabelled fallback: still keep the text on the canvas if one side can. */
      var fb = labelBox(spec, tw, r, x, y, pref), side = pref;
      if (fb.x0 < 2 || fb.x1 > w - 2) {
        var alt = labelBox(spec, tw, r, x, y, -pref);
        if (alt.x0 >= 2 && alt.x1 <= w - 2) { fb = alt; side = -pref; }
      }
      return { x: x, y: y, side: side, box: fb, labelled: false };
    }

    /* Search outward from a preferred direction until something fits. Pushing
       the radius out on each miss is what lets branches settle into whatever
       space the copy leaves rather than piling up on one side. In soft mode
       the first legal dot is remembered, but a spot that also clears the
       label wins if one turns up within the budget. */
    function searchDir(ox, oy, ang, spread, r0, step, tries, gap, spec, tw, r, mode, extra) {
      var fallback = null;
      for (var t = 0; t < tries; t++) {
        var a = ang + (rand() - 0.5) * spread;
        var rr = r0 + t * step + rand() * step * 4;
        var x = ox + Math.cos(a) * rr, y = oy + Math.sin(a) * rr;
        var hit = tryAt(x, y, gap, spec, tw, r, mode !== 'none', extra);
        if (hit) return hit;
        if (mode === 'soft' && !fallback) fallback = tryAt(x, y, gap, spec, tw, r, false, extra);
      }
      return fallback;
    }

    /* Nearest-first scan around a point, in rings seven pixels apart, so a
       displaced node still lands as close to its own branch as it can. In
       soft mode the hunt for a clear label stops at `reach`: past that, a
       close dot with a folded label beats a far one with a clear label. */
    function spiral(ox, oy, gap, spec, tw, r, mode, extra, reach) {
      var fallback = null;
      for (var rr = 0; rr < maxR; rr += 7) {
        if (fallback && reach && rr > reach) return fallback;
        var steps = Math.max(1, Math.round(TAU * rr / 7));
        var a0 = rand() * TAU;
        for (var s = 0; s < steps; s++) {
          var a = a0 + (s / steps) * TAU;
          var x = ox + Math.cos(a) * rr, y = oy + Math.sin(a) * rr;
          if (x < 0 || x > w || y < 0 || y > h) continue;
          var hit = tryAt(x, y, gap, spec, tw, r, mode !== 'none', extra);
          if (hit) return hit;
          if (mode === 'soft' && !fallback) fallback = tryAt(x, y, gap, spec, tw, r, false, extra);
        }
      }
      return fallback;
    }

    /* Placement ladder. Directional search, then nearest legal spot, then
       the node spacing relaxes in steps, then the label gives up its resting
       place. The copy and the silhouette are never relaxed, and a node is
       never dropped: losing one loses content. */
    function placeNode(pref, gap, spec, tw, r, mode, extra) {
      var hit = searchDir(pref.ox, pref.oy, pref.ang, pref.spread, pref.r0,
                          pref.step, pref.tries, gap, spec, tw, r, mode, extra);
      var ix = pref.ox + Math.cos(pref.ang) * pref.r0;
      var iy = pref.oy + Math.sin(pref.ang) * pref.r0;
      var reach = pref.r0 * (mode === 'soft' ? 4 : 3);
      /* The cone may only have offered a dot with a folded label; a clear
         label a little off-axis is worth more than that. */
      if (!hit || (mode === 'soft' && !hit.labelled)) {
        var alt = spiral(ix, iy, gap, spec, tw, r, mode, extra, reach);
        if (alt && (alt.labelled || !hit)) hit = alt;
      }
      if (!hit) hit = spiral(ix, iy, gap * 0.6, spec, tw, r, mode, extra, reach);
      if (!hit && mode !== 'none') hit = spiral(ix, iy, gap * 0.6, spec, tw, r, 'none');
      if (!hit) hit = spiral(ix, iy, gap * 0.35, spec, tw, r, 'none');
      if (!hit) hit = spiral(ix, iy, 4, spec, tw, r, 'none');
      return hit;
    }

    function boxesOf(list) {
      var out = [];
      for (var q = 0; q < list.length; q++) if (list[q].box) out.push(list[q].box);
      return out;
    }

    function measure(spec, label) {
      ctx.font = spec.font;
      return ctx.measureText(label).width;
    }

    function add(level, label, hue, parent, hub, hit, tw, spec) {
      var restLabel = level === 1 || (level === 2 && !mobile && hit.labelled);
      var n = {
        level: level, label: label, hue: hue,
        parent: parent, hub: hub, children: [],
        bx: hit.x, by: hit.y, x: hit.x, y: hit.y,
        r: compact ? spec.rc : spec.r,
        tw: tw, side: hit.side, box: hit.box,
        restLabel: restLabel,
        /* A branch label that could not find a clear resting place folds
           away and behaves like a leaf's: on when the branch is reached for. */
        collapsed: level === 2 && !mobile && !hit.labelled,
        color: hslToRgb(hue, theme.sat, theme.light),
        ph: rand() * TAU,
        s1: 0.10 + rand() * 0.13, s2: 0.06 + rand() * 0.09,
        /* Labelled nodes drift less: their label travels with them, and the
           clearance between labels is only a few pixels. */
        a1: restLabel ? 1.4 + rand() * 1.0 : 3 + rand() * 3,
        a2: restLabel ? 0.7 + rand() * 0.6 : 1.5 + rand() * 2,
        hot: 0, show: level === 1 ? 1 : 0
      };
      if (parent) parent.children.push(n);
      nodes.push(n);
      if (restLabel) labels.push(n.box);
      return n;
    }

    var hubGap = compact ? LEVEL[1].gapc : LEVEL[1].gap;
    var l2Gap = compact ? LEVEL[2].gapc : LEVEL[2].gap;
    var l3Gap = compact ? LEVEL[3].gapc : LEVEL[3].gap;
    var hubR0 = (compact ? 0.58 : 0.66) * Math.max(p.w, p.h);
    var l2R0 = compact ? 28 : 44;
    var l3R0 = compact ? 18 : 24;
    var hubs = data.hubs, hubNodes = [], hub, branch, leaf, hd, bd, ld, tw;

    /* ---- level 1: the hubs, one per compass point around him ---- */
    for (i = 0; i < hubs.length; i++) {
      hd = hubs[i];
      var baseAng = -Math.PI / 2 + i * (TAU / hubs.length);
      tw = measure(LEVEL[1], hd.label);
      var hr = compact ? LEVEL[1].rc : LEVEL[1].r;
      var hubPref = { ox: cx, oy: cy, ang: baseAng, spread: 0.55, r0: hubR0, step: 3.5, tries: 90 };
      /* First with room for the branches that will hang off it; if nowhere
         roomy is legal, the ordinary ladder still finds it a seat. */
      roomTest = roomAt;
      var hubHit = searchDir(cx, cy, baseAng, 0.55, hubR0, 3.5, 90, hubGap, LEVEL[1], tw, hr, 'strict') ||
                   spiral(cx + Math.cos(baseAng) * hubR0, cy + Math.sin(baseAng) * hubR0,
                          hubGap, LEVEL[1], tw, hr, 'strict');
      roomTest = null;
      if (!hubHit) hubHit = placeNode(hubPref, hubGap, LEVEL[1], tw, hr, 'strict');
      if (!hubHit) continue;   // only if the canvas is literally full
      hub = add(1, hd.label, hd.hue, null, null, hubHit, tw, LEVEL[1]);
      hub.hub = hub;
      hub.data = hd;
      hubNodes.push(hub);
      /* Spoke inward to a single point behind the portrait. Terminating on his
         outline tethered the graph to his edges; converging on a centre lets
         the clusters float free behind him instead. */
      edges.push({ a: hub, toCenter: true, level: 1 });
    }

    /* ---- level 2: branches fan away from the centre through their hub ---- */
    for (i = 0; i < hubNodes.length; i++) {
      hub = hubNodes[i];
      hd = hub.data;
      delete hub.data;
      var kids = hd.children || [];
      var outAng = Math.atan2(hub.by - cy, hub.bx - cx);
      var m = kids.length;
      for (j = 0; j < m; j++) {
        bd = kids[j];
        var lean = outAng + (j - (m - 1) / 2) * 0.6;
        tw = measure(LEVEL[2], bd.label);
        /* On a phone the branches open together, so keep them clear of each
           other even though none of them rests with its label on. */
        var bHit = placeNode(
          { ox: hub.bx, oy: hub.by, ang: lean, spread: 0.35, r0: l2R0, step: 2.2, tries: 40 },
          l2Gap, LEVEL[2], tw, compact ? LEVEL[2].rc : LEVEL[2].r,
          mobile ? 'soft' : 'strict', boxesOf(hub.children));
        if (!bHit) continue;
        branch = add(2, bd.label, hd.hue, hub, hub, bHit, tw, LEVEL[2]);
        branch.data = bd;
        edges.push({ a: hub, b: branch, level: 2 });
      }
    }

    /* ---- level 3: leaves fan onward from each branch at a shorter reach ---- */
    var branches = nodes.filter(function (n) { return n.level === 2; });
    for (i = 0; i < branches.length; i++) {
      branch = branches[i];
      var leaves = branch.data.children || [];
      var fwd = Math.atan2(branch.by - branch.hub.by, branch.bx - branch.hub.bx);
      var q = leaves.length;
      for (k = 0; k < q; k++) {
        ld = leaves[k];
        var lean3 = fwd + (k - (q - 1) / 2) * 0.55;
        tw = measure(LEVEL[3], ld.label);
        /* Leaves show beside their siblings and, on a phone, beside the
           hub's open branches, so those are the labels to stay clear of. */
        var lHit = placeNode(
          { ox: branch.bx, oy: branch.by, ang: lean3, spread: 0.3, r0: l3R0, step: 1.8, tries: 40 },
          l3Gap, LEVEL[3], tw, compact ? LEVEL[3].rc : LEVEL[3].r, 'soft',
          boxesOf(branch.children).concat(boxesOf(branch.hub.children)));
        if (!lHit) continue;
        leaf = add(3, ld.label, branch.hue, branch, branch.hub, lHit, tw, LEVEL[3]);
        edges.push({ a: branch, b: leaf, level: 3 });
      }
      delete branch.data;
    }

    /* ---- cross-links: pairs that belong together across hubs ---- */
    var byLabel = {};
    for (i = 0; i < nodes.length; i++) {
      if (!byLabel.hasOwnProperty(nodes[i].label)) byLabel[nodes[i].label] = nodes[i];
    }
    for (i = 0; i < data.crossLinks.length; i++) {
      var pair = data.crossLinks[i];
      var a = pair && byLabel[pair[0]], b = pair && byLabel[pair[1]];
      if (!a || !b || a === b) {
        if (global.console) console.warn('hero-scene: cross-link skipped, label not found:', pair);
        continue;
      }
      links.push({ a: a, b: b, on: 0 });
    }

    /* ---- audit: resting labels that still collide ---- */
    var overlaps = 0, rest = [];
    for (i = 0; i < nodes.length; i++) if (nodes[i].restLabel) rest.push(nodes[i]);
    for (i = 0; i < rest.length; i++) {
      var bi = rest[i].box;
      var bad = bi.x0 < 2 || bi.x1 > w - 2 || bi.y0 < 2 || bi.y1 > h - 2;
      for (q = 0; q < keepOutL.length && !bad; q++) if (boxesHit(bi, keepOutL[q])) bad = true;
      if (bad) { overlaps++; rest[i].clash = true; }
      for (j = i + 1; j < rest.length; j++) {
        if (boxesHit(bi, rest[j].box)) {
          overlaps++;
          rest[i].clash = true; rest[j].clash = true;
        }
      }
    }

    return { nodes: nodes, edges: edges, links: links, overlaps: overlaps, seed: seed };
  };

  /* Last resort after the best seed: a branch label that still collides
     folds away until its branch is hovered. Hub labels always stay. */
  HeroScene.prototype.collapseOverlaps = function (nodes) {
    var count = 0;
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      if (n.level === 2 && n.clash && n.restLabel) {
        n.restLabel = false; n.collapsed = true; count++;
      }
    }
    return count;
  };

  /* The graph is canvas, so its content is invisible to assistive tech and to
     keyboard users. Mirror the whole tree into the DOM once, nested. */
  HeroScene.prototype.renderA11yList = function (data) {
    var list = document.getElementById('heroNodeList');
    if (!list || list.childElementCount) return;
    function fill(ul, items) {
      for (var i = 0; i < items.length; i++) {
        var li = document.createElement('li');
        li.appendChild(document.createTextNode(items[i].label));
        if (items[i].children && items[i].children.length) {
          var sub = document.createElement('ul');
          fill(sub, items[i].children);
          li.appendChild(sub);
        }
        ul.appendChild(li);
      }
    }
    fill(list, data.hubs);
  };

  HeroScene.prototype.applyTheme = function () {
    var light = document.documentElement.classList.contains('light');
    var ramp = RAMPS[light ? 'light' : 'dark'];
    this.colors = [];
    for (var i = 0; i < LEVELS; i++) {
      this.colors.push(rampColor(ramp, i / (LEVELS - 1)));
    }
    var nc = NODE_COLORS[light ? 'light' : 'dark'];
    this.nodeColors = nc;
    /* Branch colours are baked at build time, so re-derive them whenever the
       theme flips or the graph would keep the other theme's palette. */
    for (i = 0; i < this.nodes.length; i++) {
      var n = this.nodes[i];
      if (n.hue != null) n.color = hslToRgb(n.hue, nc.sat, nc.light);
    }
    this.cacheValid = false;
    this.draw();
  };

  /* ============================================================
     Events
     ============================================================ */
  HeroScene.prototype.bind = function () {
    var self = this, el = this.canvas;

    el.addEventListener('pointermove', function (e) {
      var b = el.getBoundingClientRect();
      self.pointer.x = e.clientX - b.left;
      self.pointer.y = e.clientY - b.top;
      self.pointer.inside = true;
      self.pickHover();
      self.start();
    });
    el.addEventListener('pointerleave', function () {
      self.pointer.inside = false;
      self.pointer.x = -9999; self.pointer.y = -9999;
      self.setHover(null);
      self.start();
    });
    el.addEventListener('pointerdown', function (e) {
      var b = el.getBoundingClientRect();
      self.pointer.x = e.clientX - b.left;
      self.pointer.y = e.clientY - b.top;
      self.pointer.inside = true;
      self.pickHover();
      self.select(self.hover);        // null clears, so tapping empty space closes
      self.start();
    });
    el.addEventListener('pointerup', function () {
      /* Touch has no hover state to hold on to. */
      if (!global.matchMedia || !global.matchMedia('(hover: hover)').matches) {
        self.pointer.inside = false;
        self.pointer.x = -9999; self.pointer.y = -9999;
        self.setHover(null);
        self.start();
      }
    });
    el.addEventListener('pointercancel', function () {
      self.pointer.inside = false;
      self.pointer.x = -9999; self.pointer.y = -9999;
      self.start();
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && self.selected) self.select(null);
    });

    global.addEventListener('resize', this._onResize, { passive: true });

    if (global.IntersectionObserver) {
      new IntersectionObserver(function (entries) {
        self.visible = entries[0].isIntersecting;
        if (self.visible) self.start();
      }, { threshold: 0 }).observe(el);
    }
  };

  HeroScene.prototype.pickHover = function () {
    /* Every node is a target; none are faded out of reach. The hit radius is
       well beyond the drawn dot so a 2px circle is still comfortable to catch,
       and a label that is showing counts for its node too. */
    var px = this.pointer.x, py = this.pointer.y;
    var best = null, bestD = Infinity, i, n;
    for (i = 0; i < this.nodes.length; i++) {
      n = this.nodes[i];
      var d = Math.hypot(n.x - px, n.y - py);
      if (d < n.r + 13 && d < bestD) { bestD = d; best = n; }
    }
    if (!best) {
      for (i = 0; i < this.nodes.length; i++) {
        n = this.nodes[i];
        var L = n.lbl;   // where the label was actually drawn last frame
        if (!L || n.show < 0.5) continue;
        if (px > L.x0 && px < L.x1 && py > L.y0 && py < L.y1) { best = n; break; }
      }
    }
    this.setHover(best);
  };

  HeroScene.prototype.setHover = function (n) {
    if (this.hover === n) return;
    this.hover = n;
    this.canvas.style.cursor = n ? 'pointer' : '';
  };

  HeroScene.prototype.select = function (n) {
    this.selected = n;
    this.start();
    if (!this.card) return;
    if (!n) { this.card.classList.remove('is-open'); return; }
    /* Eyebrow is the path down the tree, body is the node itself, so a leaf
       reads "BUILDING / I LOVE PRODUCT PEOPLE" over "36 outreach messages",
       and a hub reads its own name over the branches it holds. */
    var crumbs;
    if (n.level === 3) crumbs = [n.hub.label, n.parent.label];
    else if (n.level === 2) crumbs = [n.hub.label];
    else crumbs = [n.label];
    var body = n.level === 1
      ? n.children.map(function (c) { return c.label; }).join(' · ')
      : n.label;
    this.card.querySelector('.hero__node-label').textContent = crumbs.join(' / ');
    this.card.querySelector('.hero__node-detail').textContent = body;
    this.card.classList.add('is-open');
    this.positionCard();
  };

  HeroScene.prototype.positionCard = function () {
    var n = this.selected;
    if (!n || !this.card) return;
    /* Always opens to the right of its node. The headline fills the left of
       the hero at display size, so opening outward from the portrait would
       drop the readout straight onto the type. Node coordinates are
       canvas-relative; the card sits in the padded scene box. */
    var ox = this.canvas.offsetLeft, oy = this.canvas.offsetTop;
    var cw = this.card.offsetWidth, ch = this.card.offsetHeight;

    var left = n.x + 14;
    var flip = left + cw > this.w - 4;   // no room right: fold back over the node
    if (flip) left = n.x - 14 - cw;

    this.card.classList.toggle('is-flipped', flip);
    this.card.style.left = Math.round(clamp(left, 4, this.w - cw - 4) + ox) + 'px';
    this.card.style.top = Math.round(clamp(n.y - ch / 2, 4, this.h - ch - 4) + oy) + 'px';
  };

  HeroScene.prototype._onResize = function () {
    var self = this;
    clearTimeout(this._rt);
    this._rt = setTimeout(function () { self.rebuild(); }, 160);
  };

  /* ============================================================
     Loop
     ============================================================ */
  HeroScene.prototype.start = function () {
    if (this.running || !this.dots) return;
    /* The intersection observer can be left saying "off screen" by a resize
       that reflowed the hero under it. Anything that asks the loop to run
       (a pointer, a tap, a theme flip) checks the geometry instead. */
    if (!this.visible && this.inView()) this.visible = true;
    this.running = true;
    requestAnimationFrame(this._frame);
  };

  HeroScene.prototype.inView = function () {
    var r = this.canvas.getBoundingClientRect();
    return r.bottom > 0 && r.right > 0 &&
           r.top < (global.innerHeight || document.documentElement.clientHeight) &&
           r.left < (global.innerWidth || document.documentElement.clientWidth);
  };

  HeroScene.prototype._frame = function () {
    this.running = false;
    if (!this.visible) return;

    var settled = this.stepDots();
    var calm = true;
    if (this.withGraph) calm = this.stepGraph();
    this.draw();
    if (this.selected) this.positionCard();

    /* The nodes drift continuously, so the loop only sleeps when the graph is
       off or motion is reduced, the dot field has come to rest and every
       hover and reveal has finished easing. */
    var live = (this.withGraph && !this.reduced) || this.pointer.inside || !settled || !calm;
    if (live) this.start();
  };

  HeroScene.prototype.stepDots = function () {
    var dots = this.dots, n = dots.length;
    var px = this.pointer.x, py = this.pointer.y;
    var on = this.pointer.inside && !this.reduced;
    var R = this.radius, R2 = R * R, S = this.strength;
    var settled = true;

    for (var i = 0; i < n; i++) {
      var d = dots[i];
      var tx = 0, ty = 0;
      if (on) {
        /* Forces sample the dot's rest position, not its current one, so the
           deformation is a stable field that follows the cursor and every dot
           has a rest state to return to. */
        var ax = px - d.x, ay = py - d.y;
        var d2 = ax * ax + ay * ay;
        if (d2 < R2) {
          var dist = Math.sqrt(d2) || 0.001;
          var f = (1 - dist / R); f *= f;
          tx = -(ax / dist) * S * f;
          ty = -(ay / dist) * S * f;
        }
      }
      d.vx = (d.vx + (tx - d.dx) * 0.11) * 0.84;
      d.vy = (d.vy + (ty - d.dy) * 0.11) * 0.84;
      d.dx += d.vx; d.dy += d.vy;

      if (settled &&
          (Math.abs(d.dx) > 0.06 || Math.abs(d.dy) > 0.06 ||
           Math.abs(d.vx) > 0.02 || Math.abs(d.vy) > 0.02)) settled = false;
    }
    if (!settled) this.cacheValid = false;
    return settled;
  };

  /* Which nodes a hover or selection reaches across a cross-link. */
  HeroScene.prototype.linkedTo = function (n) {
    var out = [];
    if (!n) return out;
    for (var i = 0; i < this.links.length; i++) {
      var l = this.links[i];
      if (l.a === n) out.push(l.b);
      else if (l.b === n) out.push(l.a);
    }
    return out;
  };

  /* How warm a node should run this frame. 1 under the cursor or when open;
     a share of that for the nodes the interaction reaches: the children of
     the focused node, its siblings when it is a leaf, its parent, and
     whatever it is cross-linked to. On a phone the tapped hub's branches
     count as reached, which is what opens them. */
  HeroScene.prototype.heatOf = function (n, focus, linked) {
    var best = 0, f, i;
    for (i = 0; i < focus.length; i++) {
      f = focus[i];
      if (!f) continue;
      var v = 0;
      if (f === n) v = 1;
      else if (n.parent === f) v = 0.7;
      else if (linked[i].indexOf(n) !== -1) v = 0.6;
      else if (n.level === 3 && f.level === 3 && f.parent === n.parent) v = 0.45;
      else if (f.parent === n) v = 0.3;
      else if (this.mobile && n.level === 2 && f.hub === n.hub) v = 0.5;
      if (v > best) best = v;
    }
    return best;
  };

  /* Drift, hover repulsion and the easing of every hot/show value. Returns
     true once nothing is still easing, so the loop can sleep under reduced
     motion. */
  HeroScene.prototype.stepGraph = function () {
    var drift = !this.reduced;
    var ease = this.reduced ? 1 : 0.18;
    if (drift) this.t += 0.016;
    var t = this.t, nodes = this.nodes;
    var px = this.pointer.x, py = this.pointer.y, on = this.pointer.inside;
    var focus = [this.hover, this.selected];
    var linked = [this.linkedTo(this.hover), this.linkedTo(this.selected)];
    var calm = true, i, n;

    for (i = 0; i < nodes.length; i++) {
      n = nodes[i];
      if (drift) {
        /* Two out-of-phase sines per axis: continuous, never repeating on a
           short cycle, and stable without a physics solver. */
        var x = n.bx + Math.sin(t * n.s1 + n.ph) * n.a1 +
                       Math.sin(t * n.s2 * 1.7 + n.ph * 2.1) * n.a2;
        var y = n.by + Math.cos(t * n.s2 + n.ph * 1.3) * n.a1 * 0.8 +
                       Math.cos(t * n.s1 * 1.4 + n.ph) * n.a2 * 0.7;
        /* The field parts around the cursor, except for the node under it:
           that one holds still so its label and hit area do not wander. */
        if (on && n !== this.hover) {
          var ax = x - px, ay = y - py, d = Math.hypot(ax, ay);
          if (d < 90 && d > 0.001) {
            var f = (1 - d / 90); f *= f * 10;
            x += (ax / d) * f; y += (ay / d) * f;
          }
        }
        n.x = x; n.y = y;
      }

      var heat = this.heatOf(n, focus, linked);
      /* Hub labels always show. Branch labels show at rest on desktop unless
         they had to fold, and open with their hub on a phone. Leaf labels
         show only while the interaction reaches them. */
      var show = n.level === 1 ? 1 : (n.restLabel ? 1 : (heat > 0 ? 1 : 0));

      var dh = heat - n.hot, ds = show - n.show;
      if (Math.abs(dh) > 0.004 || Math.abs(ds) > 0.004) calm = false;
      n.hot += dh * ease;
      n.show += ds * ease;
    }

    for (i = 0; i < this.links.length; i++) {
      var l = this.links[i];
      var want = (l.a === this.hover || l.b === this.hover ||
                  l.a === this.selected || l.b === this.selected) ? 1 : 0;
      var dl = want - l.on;
      if (Math.abs(dl) > 0.004) calm = false;
      l.on += dl * ease;
    }
    return calm;
  };

  /* ============================================================
     Draw
     ============================================================ */
  HeroScene.prototype.draw = function () {
    if (!this.dots) return;
    var ctx = this.ctx;
    ctx.clearRect(0, 0, this.w, this.h);
    if (this.withGraph) { this.drawEdges(ctx); this.drawLinks(ctx); this.drawNodes(ctx); }
    this.drawPortrait(ctx);
  };

  /* Walk a line from its outer end toward the centre and report where it first
     meets the silhouette. Spokes aim at a point behind the portrait, so without
     this they draw straight across his face, because the dot field is full of gaps and
     a line behind it still shows through every one of them. */
  HeroScene.prototype.silhouetteHit = function (ax, ay, bx, by) {
    var p = this.portrait;
    var dx = bx - ax, dy = by - ay;
    var len = Math.hypot(dx, dy) || 1;
    /* Fixed 4px stride rather than a fixed step count: a long spoke sampled in
       28 steps overshoots by half a step and lands inside him. */
    var n = Math.ceil(len / 4);
    for (var i = 0; i <= n; i++) {
      var t = i / n;
      var x = ax + dx * t, y = ay + dy * t;
      if (x < p.x || x > p.x + p.w || y < p.y || y > p.y + p.h) continue;
      if (this.sample((x - p.x) / p.w, (y - p.y) / p.h)[1] > 0.12) {
        /* Stop clear of the silhouette, not on it. */
        var tb = Math.max(0, t - 20 / len);
        return { x: ax + dx * tb, y: ay + dy * tb, cut: true };
      }
    }
    return { x: bx, y: by, cut: false };
  };

  /* A segment that reaches him fades out before it arrives, so it reads as
     passing behind rather than stopping against an edge. */
  HeroScene.prototype.fadeTo = function (ctx, ax, ay, end, rgb, alpha) {
    var g = ctx.createLinearGradient(ax, ay, end.x, end.y);
    g.addColorStop(0, 'rgba(' + rgb.join(',') + ',' + alpha + ')');
    g.addColorStop(0.35, 'rgba(' + rgb.join(',') + ',' + alpha + ')');
    g.addColorStop(1, 'rgba(' + rgb.join(',') + ',0)');
    ctx.strokeStyle = g;
    ctx.beginPath();
    ctx.moveTo(ax, ay);
    ctx.lineTo(end.x, end.y);
    ctx.stroke();
  };

  HeroScene.prototype.drawEdges = function (ctx) {
    var C = this.nodeColors, e, i, end, heat;
    var kx = this.portrait.cx, ky = this.portrait.cy;
    var flat = 'rgba(' + C.edge.join(',') + ',' + C.edgeA + ')';
    /* Leaf edges run fainter than branch edges so the tree reads in depth. */
    var faint = 'rgba(' + C.edge.join(',') + ',' + (C.edgeA * 0.6) + ')';
    var warm = [], trimmed = [];
    ctx.lineWidth = 1;

    /* Everything cool that never touches him is two batched paths. */
    for (var pass = 0; pass < 2; pass++) {
      ctx.beginPath();
      for (i = 0; i < this.edges.length; i++) {
        e = this.edges[i];
        if ((e.level === 3) !== (pass === 1)) continue;
        heat = Math.max(e.a.hot, e.b ? e.b.hot : 0);
        if (heat > 0.02) { warm.push(e); continue; }
        end = this.silhouetteHit(e.a.x, e.a.y,
                                 e.toCenter ? kx : e.b.x, e.toCenter ? ky : e.b.y);
        if (end.cut) { trimmed.push({ e: e, end: end, heat: 0 }); continue; }
        ctx.moveTo(e.a.x, e.a.y);
        ctx.lineTo(end.x, end.y);
      }
      ctx.strokeStyle = pass === 0 ? flat : faint;
      ctx.stroke();
    }

    /* Warm edges take the hot colour in proportion to the warmer of their
       ends, which is what lights a branch's leaves together. */
    for (i = 0; i < warm.length; i++) {
      e = warm[i];
      heat = Math.max(e.a.hot, e.b ? e.b.hot : 0);
      end = this.silhouetteHit(e.a.x, e.a.y,
                               e.toCenter ? kx : e.b.x, e.toCenter ? ky : e.b.y);
      if (end.cut) { trimmed.push({ e: e, end: end, heat: heat }); continue; }
      ctx.strokeStyle = this.edgeStyle(e, heat);
      ctx.beginPath();
      ctx.moveTo(e.a.x, e.a.y);
      ctx.lineTo(end.x, end.y);
      ctx.stroke();
    }

    for (i = 0; i < trimmed.length; i++) {
      var tr = trimmed[i];
      var base = tr.e.level === 3 ? C.edgeA * 0.6 : C.edgeA;
      var rgb = [Math.round(lerp(C.edge[0], C.edgeHot[0], tr.heat)),
                 Math.round(lerp(C.edge[1], C.edgeHot[1], tr.heat)),
                 Math.round(lerp(C.edge[2], C.edgeHot[2], tr.heat))];
      this.fadeTo(ctx, tr.e.a.x, tr.e.a.y, tr.end, rgb, lerp(base, C.edgeHotA, tr.heat));
    }
  };

  HeroScene.prototype.edgeStyle = function (e, heat) {
    var C = this.nodeColors;
    var base = e.level === 3 ? C.edgeA * 0.6 : C.edgeA;
    return 'rgba(' +
      Math.round(lerp(C.edge[0], C.edgeHot[0], heat)) + ',' +
      Math.round(lerp(C.edge[1], C.edgeHot[1], heat)) + ',' +
      Math.round(lerp(C.edge[2], C.edgeHot[2], heat)) + ',' +
      lerp(base, C.edgeHotA, heat) + ')';
  };

  /* Cross-links only exist while one end is reached for. They are dashed and
     thin so they never read as part of the tree, and they are trimmed from
     both ends because they usually run straight across him. */
  HeroScene.prototype.drawLinks = function (ctx) {
    var C = this.nodeColors;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 5]);
    for (var i = 0; i < this.links.length; i++) {
      var l = this.links[i];
      if (l.on < 0.02) continue;
      var alpha = C.edgeHotA * 0.7 * l.on;
      var a = l.a, b = l.b;
      var hitA = this.silhouetteHit(a.x, a.y, b.x, b.y);
      if (!hitA.cut) {
        ctx.strokeStyle = 'rgba(' + C.edgeHot.join(',') + ',' + alpha + ')';
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
        continue;
      }
      this.fadeTo(ctx, a.x, a.y, hitA, C.edgeHot, alpha);
      var hitB = this.silhouetteHit(b.x, b.y, a.x, a.y);
      this.fadeTo(ctx, b.x, b.y, hitB, C.edgeHot, alpha);
    }
    ctx.setLineDash([]);
  };

  HeroScene.prototype.drawNodes = function (ctx) {
    var rest = this.nodeColors.rest, w = this.w, h = this.h;
    var i, n, dyn = [], fixed = [];

    for (i = 0; i < this.nodes.length; i++) {
      n = this.nodes[i];
      var hot = n.hot;
      var r = n.r * (1 + hot * 0.55);

      /* Neutral and quiet until reached for, then its branch's colour at full
         strength. Colour is the reward for the interaction, not the default. */
      var restA = n.level === 3 ? REST_ALPHA * 0.8 : REST_ALPHA;
      ctx.globalAlpha = restA + hot * (1 - restA);
      ctx.fillStyle = mixRgb(rest, n.color, hot);
      ctx.beginPath();
      ctx.arc(n.x, n.y, r, 0, TAU);
      ctx.fill();

      /* The open card already names the selected node; a canvas label beside it
         would just say it twice. */
      n.lbl = null;
      if (n.show <= 0.02 || n === this.selected) continue;
      var spec = LEVEL[n.level];
      /* The side was chosen at layout. Fold back only if drift or a tight
         canvas would run the text off the edge. */
      var side = n.side, off = n.r + LABEL_GAP;
      if (side > 0 && n.x + off + n.tw > w - 2) side = -1;
      else if (side < 0 && n.x - off - n.tw < 2) side = 1;
      var lx = n.x + side * off;
      var item = { n: n, spec: spec, side: side, lx: lx, y: n.y,
                   hh: spec.size * 0.62 + LABEL_PAD_Y,
                   x0: (side > 0 ? lx : lx - n.tw) - LABEL_PAD_X,
                   x1: (side > 0 ? lx + n.tw : lx) + LABEL_PAD_X };
      (n.restLabel ? fixed : dyn).push(item);
    }

    /* Labels that only show on interaction were never promised a clear spot,
       so they are settled now: slid vertically off each other and off the
       resting labels, with a leader tying a moved label back to its dot.
       Resting labels never move; the layout already cleared them. */
    if (dyn.length) settleLabels(dyn, fixed, h);

    ctx.textBaseline = 'middle';
    ctx.lineWidth = 1;
    var all = fixed.concat(dyn);
    for (i = 0; i < all.length; i++) {
      var it = all[i];
      n = it.n;
      var a = n.show * lerp(it.spec.restA, 0.96, n.hot);
      var col = mixRgb(rest, n.color, n.hot);
      ctx.globalAlpha = a;
      ctx.fillStyle = col;
      ctx.font = it.spec.font;
      ctx.textAlign = it.side > 0 ? 'left' : 'right';
      ctx.fillText(n.label, it.lx, it.y + 0.5);
      if (Math.abs(it.y - n.y) > 3) {
        ctx.globalAlpha = a * 0.45;
        ctx.strokeStyle = col;
        ctx.beginPath();
        ctx.moveTo(n.x + it.side * (n.r + 1.5), n.y);
        ctx.lineTo(it.lx - it.side * 2, it.y);
        ctx.stroke();
      }
      n.lbl = { x0: it.x0, x1: it.x1, y0: it.y - it.hh, y1: it.y + it.hh };
    }
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.globalAlpha = 1;
  };

  /* Push the revealed labels apart vertically until none overlaps another
     revealed label or a resting one. A few relaxation passes settle the
     handful that ever show at once. */
  function settleLabels(dyn, fixed, h) {
    var i, j, a, b, d;
    dyn.sort(function (p, q) { return p.y - q.y; });
    for (var iter = 0; iter < 8; iter++) {
      var moved = false;
      /* Revealed labels share the overlap between them. */
      for (i = 0; i < dyn.length; i++) {
        a = dyn[i];
        for (j = i + 1; j < dyn.length; j++) {
          b = dyn[j];
          if (a.x0 >= b.x1 || a.x1 <= b.x0) continue;
          d = (a.hh + b.hh) - Math.abs(a.y - b.y);
          if (d <= 0) continue;
          var half = d / 2 + 0.25;
          if (a.y <= b.y) { a.y -= half; b.y += half; }
          else { a.y += half; b.y -= half; }
          moved = true;
        }
      }
      /* Resting labels are hard, so this runs last and its result stands. */
      for (i = 0; i < dyn.length; i++) {
        a = dyn[i];
        a.y = clamp(a.y, a.hh + 1, h - a.hh - 1);
        if (clearOfFixed(a, fixed, h)) moved = true;
      }
      if (!moved) break;
    }
  }

  /* Move one revealed label to the nearest y, on the canvas, that clears
     every resting label it shares a column with. Solved as free slots on
     the y axis rather than pairwise pushes, so a label caught between two
     resting ones whose gap has closed is lifted out instead of rattling
     between them. Returns true if it moved. */
  function clearOfFixed(a, fixed, h) {
    var bands = [], j, k, b, span;
    var top = a.hh + 1, bottom = h - a.hh - 1;
    for (j = 0; j < fixed.length; j++) {
      b = fixed[j];
      if (a.x0 >= b.x1 || a.x1 <= b.x0) continue;
      span = a.hh + b.hh;
      bands.push([b.y - span, b.y + span]);
    }
    if (!bands.length) return false;
    function blocked(v) {
      if (v < top || v > bottom) return true;
      for (k = 0; k < bands.length; k++) if (v > bands[k][0] && v < bands[k][1]) return true;
      return false;
    }
    if (!blocked(a.y)) return false;
    var best = a.y, bestD = Infinity, lo, hi;
    for (j = 0; j < bands.length; j++) {
      lo = bands[j][0] - 0.25; hi = bands[j][1] + 0.25;
      if (!blocked(lo) && Math.abs(lo - a.y) < bestD) { bestD = Math.abs(lo - a.y); best = lo; }
      if (!blocked(hi) && Math.abs(hi - a.y) < bestD) { bestD = Math.abs(hi - a.y); best = hi; }
    }
    if (best === a.y) return false;
    a.y = best;
    return true;
  }

  HeroScene.prototype.drawPortrait = function (ctx) {
    /* At rest the portrait is a still image; blit the cached bitmap rather
       than re-pathing thousands of arcs behind the drifting nodes. */
    if (this.cacheValid && this.cache) {
      ctx.drawImage(this.cache, 0, 0, this.w, this.h);
      return;
    }

    var dots = this.dots, n = dots.length, i, d;
    var target = ctx;
    var settledNow = !this.pointer.inside;

    if (settledNow) {
      if (!this.cache) this.cache = document.createElement('canvas');
      if (this.cache.width !== Math.round(this.w * this.dpr)) {
        this.cache.width = Math.round(this.w * this.dpr);
        this.cache.height = Math.round(this.h * this.dpr);
      }
      target = this.cache.getContext('2d');
      target.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      target.clearRect(0, 0, this.w, this.h);
    }

    /* Bucket by luminance level: the whole field costs LEVELS fill() calls
       instead of one per dot. */
    for (var lvl = 0; lvl < LEVELS; lvl++) {
      var opened = false;
      for (i = 0; i < n; i++) {
        d = dots[i];
        if (d.lvl !== lvl) continue;
        if (!opened) { target.beginPath(); opened = true; }
        var x = d.x + d.dx, y = d.y + d.dy;
        target.moveTo(x + d.r, y);
        target.arc(x, y, d.r, 0, TAU);
      }
      if (opened) { target.fillStyle = this.colors[lvl]; target.fill(); }
    }

    if (settledNow) {
      this.cacheValid = true;
      ctx.drawImage(this.cache, 0, 0, this.w, this.h);
    }
  };

  /* ============================================================
     Boot
     ============================================================ */
  function boot() {
    var canvas = document.getElementById('heroScene');
    var wrap = document.querySelector('.hero__scene');
    if (!canvas) return;

    var withGraph = true;
    try {
      if (new URLSearchParams(global.location.search).get('portrait') === 'off') {
        withGraph = false;
      }
    } catch (e) { /* keep the default */ }

    var scene = new HeroScene(canvas, {
      card: document.getElementById('heroNodeCard'),
      withGraph: withGraph
    });

    scene.init().then(function () {
      if (wrap) wrap.classList.add('is-ready');
    }).catch(function () {
      /* Nothing to draw without the map, so drop the layer and the hero falls
         back to its text-only layout instead of leaving a hole. */
      if (wrap) wrap.remove();
    });

    /* The nav mark: the logo's dot grows into his face once you scroll past
       the hero, so the portrait stays with you down the page. On touch, where
       there is no hover to spend, this is what keeps him present. */
    var avatar = document.getElementById('navAvatar');
    var avatarScene = null;
    if (avatar) {
      avatarScene = new HeroScene(avatar, {
        withGraph: false,
        fill: true,
        crop: [0.28, 0.03, 0.72, 0.51]   // head and collar only
      });
      avatarScene.spacing = 1.6;
      avatarScene.dotScale = 0.46;
      avatarScene.floor = 0.30;
      avatarScene.init().then(function () {
        avatar.classList.add('is-ready');
        if (avatar.parentElement) {
          avatar.parentElement.classList.add('nav__logo--avatar');
        }
      }).catch(function () { avatar.remove(); });
    }

    /* Follow the site's theme toggle without coupling to its implementation. */
    if (global.MutationObserver) {
      new MutationObserver(function () {
        scene.applyTheme(); scene.start();
        if (avatarScene) { avatarScene.applyTheme(); avatarScene.start(); }
      }).observe(document.documentElement,
                 { attributes: true, attributeFilter: ['class'] });
    }

    global.__heroScene = scene;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else { boot(); }

  global.HeroScene = HeroScene;
})(window);
